use super::*;

/// A destination that does not already exist, by suffixing rather than replacing.
pub(crate) fn free_path(dir: &Path, stem: &str, ext: &str) -> PathBuf {
    let first = dir.join(if ext.is_empty() { stem.to_string() } else { format!("{stem}.{ext}") });
    if !first.exists() {
        return first;
    }
    for n in 2..1000 {
        let candidate = dir.join(if ext.is_empty() {
            format!("{stem}-{n}")
        } else {
            format!("{stem}-{n}.{ext}")
        });
        if !candidate.exists() {
            return candidate;
        }
    }
    first
}
